CREATE TABLE staging_deployments (id TEXT PRIMARY KEY, task_id TEXT NOT NULL, version_id TEXT, target_version TEXT NOT NULL, pr_url TEXT NOT NULL, task_commit TEXT NOT NULL, candidate_commit TEXT, version_branch TEXT NOT NULL, release_id TEXT, observed_git_sha TEXT, urls TEXT CHECK (urls IS NULL OR json_valid(urls)), stage TEXT NOT NULL, status TEXT NOT NULL CHECK (status IN ('running', 'succeeded', 'failed')), attempt INTEGER NOT NULL CHECK (attempt > 0), error TEXT, started_at TEXT NOT NULL, completed_at TEXT);
CREATE INDEX idx_staging_deployments_task ON staging_deployments (task_id, attempt DESC);
CREATE UNIQUE INDEX idx_staging_deployments_candidate ON staging_deployments (task_id, task_commit, candidate_commit) WHERE candidate_commit IS NOT NULL AND status = 'succeeded';
